<div class="post-list"><?php foreach ($posts as $p): ?><article class="panel post-card"><div class="author-row"><span class="avatar">B</span><div><strong><?=e(postAuthor($p['markdown']))?></strong><div class="muted"><?=e(substr($p['created_at'],0,16))?> · <?=e(t(ucfirst($p['status'])))?></div></div><a class="post-open" href="/?<?=$p['status'] === 'draft' ? 'edit' : 'post'?>=<?=$p['id']?>">Read <?=icon('arrow')?></a></div><div class="post-body"><h2><a href="/?<?=$p['status'] === 'draft' ? 'edit' : 'post'?>=<?=$p['id']?>"><?=e($p['title'])?></a></h2><p><?=e(excerpt($p['markdown']))?></p><?php $cover=postCover($p);if($cover!==''):?><a class="card-image" href="/?<?=$p['status']==='draft'?'edit':'post'?>=<?=$p['id']?>"><?php $imageSize=coverDimensions($cover);?><img <?php if($imageSize):?>width="<?=$imageSize[0]?>" height="<?=$imageSize[1]?>"<?php else:?>width="1200" height="675"<?php endif;?> src="<?=e($cover)?>" alt="<?=e(t('Post cover'))?>" loading="lazy"></a><?php endif;?><footer><a class="category-badge" href="/?category=<?=$p['category_id']?>"><?=icon('grid')?> <?=e($p['category_name'])?> ›</a><button class="text-button" data-share="/?post=<?=$p['id']?>"><?=icon('share')?> <?=e(t('Share'))?></button></footer></div></article><?php endforeach; ?><?php if (!$posts): ?><div class="panel empty"><h2><?=empty($_GET['q']) ? t('Your feed starts here') : t('No matching posts')?></h2><p><?=empty($_GET['q']) ? t('Publish a thought, a note, or something worth keeping.') : t('Try another search.')?></p></div><?php endif; ?></div><?php if ($filteredTotal > $limit): ?><nav class="pagination"><?php if ($page>1): ?><a href="<?=e('/?'.http_build_query(array_merge(array_diff_key($_GET,['edit_layout'=>1]),['page'=>$page-1])))?>">← Previous</a><?php endif; ?><span><?=$page?> / <?=(int)ceil($filteredTotal/$limit)?></span><?php if ($page*$limit<$filteredTotal): ?><a href="<?=e('/?'.http_build_query(array_merge(array_diff_key($_GET,['edit_layout'=>1]),['page'=>$page+1])))?>">Next →</a><?php endif; ?></nav><?php endif; ?>